SELECT seat_id AS seatId, status AS status, price AS price FROM seats WHERE seat_id IN
#{seatId}
FOR UPDATE

mapper.insert:
INSERT INTO bookings (
    member_id, schedule_id, total_price, status, created_at
) VALUES (
    #{memberId}, #{scheduleId}, #{totalPrice}, 'PENDING', SYSTIMESTAMP
)

INSERT INTO booking_items (
    booking_id, seat_id, unit_price
) VALUES (
    #{bookingId}, #{seatId}, #{unitPrice}
)

mapper.update:
UPDATE seats SET status = 'HELD' WHERE seat_id IN
#{seatId}
AND status = 'AVAILABLE'

UPDATE concert_schedules
SET available_seats = available_seats - #{seatCount}
WHERE schedule_id = #{scheduleId}
  AND available_seats >= #{seatCount}

UPDATE seats
SET status = 'RESERVED'
WHERE seat_id IN (
    SELECT seat_id FROM booking_items WHERE booking_id = #{bookingId}
)
AND status = 'HELD'

UPDATE bookings
SET status = 'CANCELLED',
    cancelled_at = SYSTIMESTAMP,
    cancel_reason = #{cancelReason}
WHERE booking_id = #{bookingId}
  AND status IN ('PENDING', 'CONFIRMED')

UPDATE seats
SET status = 'AVAILABLE'
WHERE seat_id IN (
    SELECT seat_id FROM booking_items WHERE booking_id = #{bookingId}
)
AND status IN ('HELD', 'RESERVED')

UPDATE concert_schedules
SET available_seats = available_seats + (
    SELECT COUNT(*) FROM booking_items WHERE booking_id = #{bookingId}
)
WHERE schedule_id = (
    SELECT schedule_id FROM bookings WHERE booking_id = #{bookingId}
)
